#' Forest Plot Builder
#'
#' 
#' @param data .
#' @param rowLabel .
#' @param rowType .
#' @param effectSize .
#' @param ciLower .
#' @param ciUpper .
#' @param weight .
#' @param leftColumns .
#' @param rightColumns .
#' @param effectCi .
#' @param effectCiLayout .
#' @param effectCiPosition .
#' @param effectCiDigits .
#' @param effectHeader .
#' @param ciHeader .
#' @param ciBrackets .
#' @param ciSeparator .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
forestPlot <- function(
    data,
    rowLabel,
    rowType,
    effectSize,
    ciLower,
    ciUpper,
    weight,
    leftColumns,
    rightColumns,
    effectCi = TRUE,
    effectCiLayout = "combined",
    effectCiPosition = "right",
    effectCiDigits = "2",
    effectHeader = "Effect Size",
    ciHeader = "95% CI",
    ciBrackets = "round",
    ciSeparator = "comma") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("forestPlot requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rowLabel)) rowLabel <- jmvcore::resolveQuo(jmvcore::enquo(rowLabel))
    if ( ! missing(rowType)) rowType <- jmvcore::resolveQuo(jmvcore::enquo(rowType))
    if ( ! missing(effectSize)) effectSize <- jmvcore::resolveQuo(jmvcore::enquo(effectSize))
    if ( ! missing(ciLower)) ciLower <- jmvcore::resolveQuo(jmvcore::enquo(ciLower))
    if ( ! missing(ciUpper)) ciUpper <- jmvcore::resolveQuo(jmvcore::enquo(ciUpper))
    if ( ! missing(weight)) weight <- jmvcore::resolveQuo(jmvcore::enquo(weight))
    if ( ! missing(leftColumns)) leftColumns <- jmvcore::resolveQuo(jmvcore::enquo(leftColumns))
    if ( ! missing(rightColumns)) rightColumns <- jmvcore::resolveQuo(jmvcore::enquo(rightColumns))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rowLabel), rowLabel, NULL),
            `if`( ! missing(rowType), rowType, NULL),
            `if`( ! missing(effectSize), effectSize, NULL),
            `if`( ! missing(ciLower), ciLower, NULL),
            `if`( ! missing(ciUpper), ciUpper, NULL),
            `if`( ! missing(weight), weight, NULL),
            `if`( ! missing(leftColumns), leftColumns, NULL),
            `if`( ! missing(rightColumns), rightColumns, NULL))

    for (v in rowType) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- forestPlotOptions$new(
        rowLabel = rowLabel,
        rowType = rowType,
        effectSize = effectSize,
        ciLower = ciLower,
        ciUpper = ciUpper,
        weight = weight,
        leftColumns = leftColumns,
        rightColumns = rightColumns,
        effectCi = effectCi,
        effectCiLayout = effectCiLayout,
        effectCiPosition = effectCiPosition,
        effectCiDigits = effectCiDigits,
        effectHeader = effectHeader,
        ciHeader = ciHeader,
        ciBrackets = ciBrackets,
        ciSeparator = ciSeparator)

    analysis <- forestPlotClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

